// Characterization tests: pin CURRENT behaviour of the orders API, bugs included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 0.1, E: 100, F: 101 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: res.status, body: await res.json() }
}
const totalOf = async (items) => (await post(items)).body.total

test('small order: no discount', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }]), 20)
  assert.equal(await totalOf([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }]), 60)
})

test('total is floored, not rounded (33.33 * 1 -> 33)', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 33)
  assert.equal(await totalOf([{ sku: 'C', qty: 2 }]), 66)
})

test('discount threshold is strictly above 100: exactly 100 gets no discount', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
})

test('just above 100 gets 10% off, then floored (101 -> 90.9 -> 90)', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90)
})

test('larger orders: 10% discount flat, no further tiers', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 8 }]), 180)   // 200 -> 180
  assert.equal(await totalOf([{ sku: 'B', qty: 40 }]), 900)  // 1000 -> 900
  assert.equal(await totalOf([{ sku: 'E', qty: 1000 }]), 90000)
  assert.equal(await totalOf([{ sku: 'C', qty: 7 }]), 209)   // 233.31 -> 209.979 -> 209
})

test('discount applies to the whole order total, mixed items', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 5 }, { sku: 'B', qty: 3 }]), 112) // 125 -> 112.5
})

test('floating point quirk: 0.1 * 3 style sums are floored after float math', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 0)
})

test('no validation of qty / unknown sku (NaN total serialises as null)', async () => {
  assert.equal(await totalOf([{ sku: 'ZZ', qty: 1 }]), null)
  assert.equal(await totalOf([{ sku: 'A', qty: -20 }]), -200)
  assert.equal(await totalOf([{ sku: 'A' }]), null)
})

test('response shape and persistence', async () => {
  const { status, body } = await post([{ sku: 'A', qty: 1 }])
  assert.equal(status, 201)
  assert.deepEqual(Object.keys(body), ['id', 'items', 'total'])
  assert.deepEqual(body.items, [{ sku: 'A', qty: 1 }])
  const got = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.deepEqual(got, body)
})

test('validation and routing quirks', async () => {
  assert.deepEqual(await post([]), { status: 400, body: { error: 'items required' } })
  const bad = await fetch(`${base}/orders`, { method: 'POST', body: '{nope' })
  assert.equal(bad.status, 400)
  const missing = await fetch(`${base}/orders/nope`)
  assert.equal(missing.status, 200) // quirk: not-found is a 200
  assert.deepEqual(await missing.json(), { error: 'not found' })
  assert.equal((await fetch(`${base}/other`)).status, 404)
})
EOF
